#include <vector>
using namespace std;

static void tron(vector<long long>& a, vector<long long>& tam, int l, int m, int r) {
    int i = l, j = m, k = l;
    while (i < m && j < r) {
        if (a[i] <= a[j]) tam[k++] = a[i++];
        else tam[k++] = a[j++];
    }
    while (i < m) tam[k++] = a[i++];
    while (j < r) tam[k++] = a[j++];
    for (int t = l; t < r; t++) a[t] = tam[t];
}

