    if (r - l < 2) return;
    int m = l + (r - l) / 2;
    chia(a, tam, l, m);
    chia(a, tam, m, r);
    tron(a, tam, l, m, r);
}

vector<long long> sap_xep(vector<long long> a) {
    vector<long long> tam(a.size());
    chia(a, tam, 0, (int)a.size());
    return a;
}
